-- GAMING CONSOLES & ACCESSORIES (8 products)
('ps5-slim-digital-edition', 'PlayStation 5 Slim Digital Edition 1TB Console', 'gaming', 580000, 569000, 495000, 10, 3.6, '/assets/products/ps5-slim-digital.jpg', 'The new slimmer, lighter PS5 Digital Edition delivers the same powerful gaming performance with a streamlined all-digital design and 1TB of ultra-fast SSD storage for instant game loading.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/ps5-slim-digital.jpg', 535000, 4.8, 1, 'Sony', 1, 1),

('xbox-series-x-2tb-galaxy', 'Xbox Series X 2TB Galaxy Black Special Edition', 'gaming', 650000, 639000, 555000, 8, 4.45, '/assets/products/xbox-series-x-galaxy.jpg', 'The most powerful Xbox ever, now with 2TB storage and a stunning galaxy-inspired design. Experience true 4K gaming at up to 120fps with the Velocity Architecture and Game Pass Ultimate ready.', 1, unixepoch('2026-06-16'), 1, 555000, '/assets/products/xbox-series-x-galaxy.jpg', 605000, 4.8, 1, 'Microsoft', 1, 1),

('nintendo-switch-2-oled', 'Nintendo Switch 2 OLED Model 256GB - Mario Kart Bundle', 'gaming', 420000, 409000, 355000, 15, 0.42, '/assets/products/switch-2-oled.jpg', 'The next generation of Nintendo hybrid gaming with a vibrant 8-inch OLED display, improved Joy-Con 2 controllers with hall-effect sticks, and backward compatibility with your existing Switch library.', 1, unixepoch('2026-06-16'), 1, 355000, '/assets/products/switch-2-oled.jpg', 388000, 4.9, 1, 'Nintendo', 1, 1),

('steam-deck-oled-1tb', 'Steam Deck OLED 1TB Handheld Gaming PC', 'gaming', 750000, 729000, 635000, 6, 0.64, '/assets/products/steam-deck-oled.jpg', 'Your entire Steam library in your hands. The OLED model features a gorgeous 7.4-inch 90Hz HDR display, improved battery life, and a custom AMD APU optimized for handheld gaming on the go.', 1, unixepoch('2026-06-16'), 1, 635000, '/assets/products/steam-deck-oled.jpg', 695000, 4.7, 0, 'Valve', 1, 1),

('asus-rog-ally-x', 'ASUS ROG Ally X 1TB Handheld Gaming PC - Black', 'gaming', 580000, 569000, 495000, 10, 0.68, '/assets/products/rog-ally-x.jpg', 'Windows 11 gaming without compromise. The ROG Ally X packs an AMD Ryzen Z2 Extreme processor and a 120Hz FHD display into an ergonomic handheld, delivering desktop-class gaming anywhere.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/rog-ally-x.jpg', 535000, 4.6, 1, 'ASUS', 1, 1),

('playstation-portal-2', 'PlayStation Portal 2 Remote Player 8" OLED', 'gaming', 220000, 215000, 185000, 18, 0.54, '/assets/products/ps-portal-2.jpg', 'Stream your PS5 games anywhere in your home with the new Portal 2. Featuring a larger 8-inch OLED screen, improved ergonomics with DualSense haptics, and Wi-Fi 6E for lag-free remote play.', 1, unixepoch('2026-06-16'), 1, 185000, '/assets/products/ps-portal-2.jpg', 205000, 4.5, 0, 'Sony', 1, 1),

('dualsense-edge-controller', 'PlayStation DualSense Edge Wireless Controller Pro', 'gaming', 185000, 179000, 152000, 15, 0.33, '/assets/products/dualsense-edge.jpg', 'Built for competitive gamers. The DualSense Edge features customizable back paddles, swappable stick modules, adjustable trigger stops, and on-the-fly profile switching for the ultimate competitive edge.', 1, unixepoch('2026-06-16'), 1, 152000, '/assets/products/dualsense-edge.jpg', 168000, 4.7, 1, 'Sony', 1, 0),

('xbox-elite-controller-3', 'Xbox Elite Wireless Controller Series 3', 'gaming', 195000, 189000, 158000, 12, 0.35, '/assets/products/xbox-elite-3.jpg', 'The pinnacle of Xbox controller design. Featuring adjustable-tension thumbsticks with new precision rings, a built-in rechargeable battery with 40-hour life, and more customization than ever before.', 1, unixepoch('2026-06-16'), 1, 158000, '/assets/products/xbox-elite-3.jpg', 178000, 4.8, 1, 'Microsoft', 1, 1),

-- DRONES (5 products)
('dji-mini-5-pro', 'DJI Mini 5 Pro Fly More Combo - Under 249g', 'drones', 950000, 929000, 810000, 8, 0.88, '/assets/products/dji-mini-5-pro.jpg', 'The ultimate travel drone stays under 249g while packing a 1-inch CMOS sensor, 4K/100fps HDR video, omnidirectional obstacle sensing, and 47-minute flight time. No registration required in most regions.', 1, unixepoch('2026-06-16'), 1, 810000, '/assets/products/dji-mini-5-pro.jpg', 880000, 4.9, 1, 'DJI', 1, 1),

('dji-air-4', 'DJI Air 4 Fly More Combo with RC 2 Controller', 'drones', 1250000, 1215000, 1050000, 6, 1.25, '/assets/products/dji-air-4.jpg', 'Pro-level aerial cinematography made accessible. The Air 4 features a dual-camera system with a 1-inch main sensor and a 70mm telephoto, full omnidirectional obstacle avoidance, and 46-minute flight time.', 1, unixepoch('2026-06-16'), 1, 1050000, '/assets/products/dji-air-4.jpg', 1150000, 4.8, 1, 'DJI', 1, 1),

('dji-neo-2', 'DJI Neo 2 Palm-Sized FPV Drone with Goggles N4', 'drones', 380000, 369000, 315000, 15, 0.35, '/assets/products/dji-neo-2.jpg', 'The perfect entry to immersive FPV flight. Launch and land from your palm, fly with or without the motion controller, and experience the thrill of first-person-view flying in a compact, beginner-friendly package.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/dji-neo-2.jpg', 348000, 4.6, 1, 'DJI', 1, 1),

('potensic-atom-3', 'Potensic Atom 3 GPS Drone 4K with 3-Axis Gimbal', 'drones', 185000, 179000, 148000, 20, 0.45, '/assets/products/potensic-atom-3.jpg', 'Premium features without the premium price. The Atom 3 delivers 4K stabilized footage via a true 3-axis gimbal, GPS auto-return, 32-minute flight time, and a 6km transmission range in a foldable design.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/potensic-atom-3.jpg', 168000, 4.5, 1, 'Potensic', 1, 1),

('holy-stone-hs720r-4k', 'Holy Stone HS720R 4K GPS Drone with Brushless Motors', 'drones', 125000, 119000, 98000, 25, 0.52, '/assets/products/holy-stone-hs720r.jpg', 'An excellent value drone featuring 4K EIS camera, GPS intelligent flight modes including follow-me and waypoints, brushless motors for quiet operation, and a robust carrying case for adventures.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/holy-stone-hs720r.jpg', 112000, 4.4, 1, 'Holy Stone', 0, 1),

