('xgimi-halo-plus-2', 'XGIMI Halo+ 2 Portable Projector 1080p Android TV', 'projectors', 350000, 339000, 288000, 10, 1.85, '/assets/products/xgimi-halo-plus-2.jpg', 'Cinema anywhere you go. The Halo+ 2 is a compact projector with built-in Harman Kardon speakers, Android TV 14 with Netflix certified, auto keystone correction, and a brilliant 900 ANSI lumen picture.', 1, unixepoch('2026-06-16'), 1, 288000, '/assets/products/xgimi-halo-plus-2.jpg', 318000, 4.7, 1, 'XGIMI', 1, 1),

