('anker-nebula-mars-4', 'Anker Nebula Mars 4 Portable Projector 4K Outdoor', 'projectors', 520000, 509000, 445000, 6, 3.8, '/assets/products/nebula-mars-4.jpg', 'Built for the great outdoors. The rugged, waterproof Mars 4 projects a stunning 4K image up to 200 inches, with a powerful 40W speaker and a massive battery for 5 hours of movie playback under the stars.', 1, unixepoch('2026-06-16'), 1, 445000, '/assets/products/nebula-mars-4.jpg', 485000, 4.7, 0, 'Anker', 1, 1),

('epson-ef-22', 'Epson EF-22 Portable Laser Projector 1000 Lumens', 'projectors', 680000, 659000, 575000, 5, 2.1, '/assets/products/epson-ef-22.jpg', 'Epson''s 3LCD laser technology delivers vivid, true-to-life colors without the rainbow effect. The EF-22 is compact, auto-focusing, and features built-in streaming for a true plug-and-play cinema experience.', 1, unixepoch('2026-06-16'), 1, 575000, '/assets/products/epson-ef-22.jpg', 625000, 4.8, 1, 'Epson', 0, 1),

('viewsonic-m2e-2', 'ViewSonic M2e 2 Instant Smart LED Projector', 'projectors', 280000, 275000, 235000, 12, 1.0, '/assets/products/viewsonic-m2e-2.jpg', 'Instant entertainment in a pocket-sized package. The M2e 2 features ToF autofocus, a built-in battery, Bluetooth speaker mode, and vibrant LED colors, making it the perfect companion for spontaneous movie nights.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/viewsonic-m2e-2.jpg', 258000, 4.5, 1, 'ViewSonic', 0, 1),

